import {FACILITIES} from './facilities.js?v=architecture-collection-44';
import {POWER_PLANTS} from './power.js?v=architecture-collection-44';
import {RECREATION} from './recreation.js?v=architecture-collection-44';
import {SERVICES,civicRoadIds} from './civic-footprints.js?v=architecture-collection-44';
import {REWARDS,rewardRoots,rewardSize,rewardActive} from './rewards.js?v=architecture-collection-44';
// Prima table 14-2, pp.216–217: structure garbage weights divided by 100.
// This maps source proportions to monthly simulation units, not original tonnage.
export const REWARD_WASTE={scienceCenter:8,stockExchange:6.4,geyserPark:10,cityHall:1.44,countryClub:10,lighthouse:1.6,medicalResearch:2.88,performingArts:1.6,stadium:36,university:88,themePark:144};
export function rewardWasteProduction(c,t){return REWARD_WASTE[t.type]&&t.root===t.y*c.size+t.x&&rewardActive(c,t)?REWARD_WASTE[t.type]:0;}
// Old waste remains collectable even while a reward has stopped operating.
export function garbageSourceRoads(c,t){if(FACILITIES[t.type]){if(c.finance.roadCondition<=20)return [];const plot=c.stats.facilityPlots?.find(p=>p.root===t.facilityRoot);return plot?[...new Set(plot.ids.flatMap(i=>c.tiles[i].roadIds||[]))]:t.roadIds||[];}if(SERVICES[t.type])return c.finance.roadCondition>20?civicRoadIds(c,t):[];if(['busStop','trainStation','subwayStation','railTransfer','recycling'].includes(t.type)&&c.finance.roadCondition<=20)return [];if((!REWARDS[t.type]&&!RECREATION[t.type]&&!POWER_PLANTS[t.type])||!Number.isInteger(t.root))return t.roadIds||[];if(c.finance.roadCondition<=20)return [];const root=c.tiles[t.root];if(!root||root.type!==t.type)return t.roadIds||[];const ids=new Set(),size=REWARDS[root.type]?rewardSize(root):(RECREATION[root.type]||POWER_PLANTS[root.type]).size;for(let y=root.y;y<root.y+size;y++)for(let x=root.x;x<root.x+size;x++){const member=c.tiles[y*c.size+x];if(member?.root===root.root)for(const id of member.roadIds||[])ids.add(id);}return [...ids];}
export function rewardWasteSources(c){return rewardRoots(c).filter(t=>REWARD_WASTE[t.type]).map(t=>({type:t.type,name:REWARDS[t.type].name,x:t.x,y:t.y,rate:rewardWasteProduction(c,t),waiting:c.tiles.filter(u=>u.root===t.root).reduce((sum,u)=>sum+u.waste,0)}));}
export function rewardWasteReport(c){const rows=rewardWasteSources(c);if(!rows.length)return '';const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});return `<details><summary>Reward buildings · garbage</summary><p>These buildings add ${fmt(rows.reduce((sum,r)=>sum+r.rate,0))} units to monthly city garbage. Each footprint is counted once. This is included in the city’s total production.</p><div class="table-scroll"><table aria-label="Reward building garbage"><thead><tr><th>Building</th><th>Location</th><th>Units/month</th><th>Waiting</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.name}</th><td>${r.x+1}, ${r.y+1}</td><td>${fmt(r.rate)}</td><td>${fmt(r.waiting)}</td></tr>`).join('')}</tbody></table></div><p>Connect a road beside any part of the footprint to disposal facilities or a garbage-export route. An isolated disposal network cannot collect this waste. New production stops when the reward stops operating; existing garbage still needs collection.</p></details>`;}
export function rewardGarbageInspection(c,t){if(!REWARD_WASTE[t.type])return '';const root=c.tiles[t.root],source=rewardWasteSources(c).find(r=>r.x===root?.x&&r.y===root?.y);return source?`<p>Garbage: ${source.rate.toFixed(2)} units/month · ${source.waiting.toFixed(2)} waiting. Collection uses road access beside the whole footprint. Connect that road network to disposal capacity or a garbage-export route.</p>`:'';}
